#!/usr/bin/env python3
import numpy as np
import importlib
from datetime import datetime
import scipy.constants as const
import catscfsp5 as cat

# does no longer calculate IP during the dynamic! (This is done by different script during dynamic)
fs2au       = 41.341374575751 # qc time is au
aulen       = const.physical_constants['atomic unit of length'][0]*1e10 # au length
#bohr2ang    = const.physical_constants['Bohr radius']*1e10 #0.5291772109 
aumas       = 1822.88848492937 # element_m = m*aumas # mH = 1, mHe = 4, ...
kbinau      = const.k/const.physical_constants['Hartree energy'][0] # 3.16681e-6 Eh/K, T = self.ekin/(3*self.N*kbinau)

element_m = np.array([1.008, 4.003, 6.941, 9.012, 10.811, 12.011, 14.007, 15.999, 18.998, 20.180, 22.990, 24.305, 26.982, 28.086, 30.974, 32.066, 35.453, 39.948, 39.098, 40.078, 44.956, 47.867, 50.942, 51.996, 54.938, 55.845, 58.933, 58.693, 63.546, 65.38, 69.723, 72.631, 74.922, 78.971, 79.904, 83.798, 85.468, 87.62, 88.906, 91.224, 92.906, 95.95, 98.907, 101.07, 102.906, 106.42, 107.868, 112.414, 114.818, 118.711, 121.760, 127.60, 126.904, 131.294, 132.905, 137.328, 138.905, 140.116, 140.908, 144.243, 144.913, 150.36, 151.964, 157.25, 158.925, 162.500, 164.930, 167.259, 168.934, 173.055, 174.967, 178.49, 180.948, 183.84, 186.207, 190.23, 192.217, 195.085, 196.967, 200.592, 204.383, 207.2, 208.980, 208.982, 209.987, 222.018, 223.020, 226.025, 227.028, 232.038, 231.036, 238.029, 237, 244, 243, 247, 247, 251, 252, 257, 258, 259, 262, 261, 262, 266, 264, 269, 268, 271, 272, 285, 284, 289, 288, 292, 294, 294]) * aumas

element_d = {1:'H', 2:'He', 6:'C', 7:'N', 8:'O', 9:'F', 10:'Ne', 47:'Ag'}
element_d_rev = dict((v,k) for k,v in element_d.items())

class VelocityVerlet():
    def __init__(self, dt, n_steps, jobname, write, Tempr, initfile, method=['qchem', 'readenergy.txt'], initstep='0'):
        self.submit = importlib.import_module('VV_8_{}'.format(method[0]))
        self.method = method
        self.n_steps = int(n_steps)
        self.log_time('w')
        self.jobname = jobname[0]
        self.dynamics = jobname[5]
        self.comname ='{}{}'.format(jobname[1], jobname[2])
        self.fchkname = '{}{}'.format(jobname[3], jobname[2])
        self.Enname = jobname[4]
        # getens: [write, read, calc] each is an array of n names (str) and n number of columns (int)
        self.getens = cat.whichenread(self.method, '{}_{}.out'.format(self.jobname, self.Enname), [0, 2])
        self.getnames = self.getens[0][0] + self.getens[1][0] # new list, getens[0][0] is still used to write the output
        self.dt = float(dt)*fs2au #scale time to au
        self.tau = float(Tempr[0])*fs2au #*41.3413733365614 old hardcode const
        self.en_thermo = bool(Tempr[2])
        self.write = int(write[0])
        self.tempxyz = write[1]

        # qi aus xyz schreiben
        atoms, pos, self.vi, self.N = self.load_inits(initfile)
        self.qi = pos.ravel()
        # alle Atomsymbole in n packen (aus .xyz-file)
        self.n = [element_d[i] for i in atoms]
        self.mass = element_m[np.array(atoms)-1]
        self.mass3 = np.repeat(self.mass, 3) # mass per cartesian component
        self.mg = np.sum(self.mass)
        self.qi = self.rem_schwerpunkt(self.qi)

        if len(initstep) > 0: #> 1: # first step with init
            self.initcalculator(self.qi, initstep)
        self.vi = self.rem_trans_rot(self.vi, self.qi)
        self.T_soll = float(Tempr[1])

        # Errechnung des Gradienten
        self.gradient = self.grad(self.qi)
        self.ai = self.grad_to_a(self.gradient)
        self.update_kinetics()
        self.writer(0)

    def calculator(self, q): # schreibt Koordinaten q in temp.xyz und gibt Rechnung an das QC-Programm. Die Ergebnisse stehen danach in self.data.
        self.data = self.submit.calc(self.comname, self.tempxyz, self.N, self.n, q, self.fchkname, self.getnames, aulen)

    def grad(self, q): # gradient at the coordinates q (not at self.qi, the propagation needs it at q_new)
        # orca and gaussian : grad in Eh/bohr
        self.calculator(q)
        return self.data['gradient']

    def grad_to_a(self, grad): # Umrechnung der Gradienten in Beschleunigung
        return -grad/self.mass3

    def v_plus_1(self):         # errechnet und setzt v+1
        self.v_new = self.vi+(self.ai+self.a_new)/2*self.dt

    def q_plus_1(self):         # errechnet und setzt q+1
        self.q_new = self.qi+self.vi*self.dt+self.ai/2*self.dt**2

    def rem_schwerpunkt(self, q):# gibt q relativ zum Schwerpunkt zurück
        r = q.reshape(-1, 3)
        return (r-self.mass.dot(r)/self.mg).ravel()

    def rem_impuls(self, v):    # gibt v-Gesammtimpuls
        w = v.reshape(-1, 3)
        return (w-self.mass.dot(w)/self.mg).ravel()

    def drehimpuls(self, q, v): # gibt Gesammtdrehimpuls zurück
        return self.mass.dot(np.cross(q.reshape(-1, 3), v.reshape(-1, 3)))

    def traegheitsmoment(self, q):# gibt Trägheitsmoment zurück
        r = q.reshape(-1, 3)
        return self.mass.dot(np.einsum('ij,ij->i', r, r))*np.identity(3)-(r.T*self.mass).dot(r)

    def v_winkel(self, traeg, dreh): # gibt Winkelgeschwindigkeit zurück
       return np.linalg.pinv(traeg).dot(dreh)

    def rem_rot(self, v, q, omega) : # zieht Winkelgeschwindigkeit von v ab und gibt dann v zurück
        return (v.reshape(-1, 3)-np.cross(omega, q.reshape(-1, 3))).ravel()

    def rem_trans_rot(self, v, q): #elliminiert Rotation und Translation von v, gibt dann v zurück
        vv = self.rem_impuls(v)
        dreh = self.drehimpuls(q, vv)
        traeg = self.traegheitsmoment(q)
        omega = self.v_winkel(traeg, dreh)
        vv = self.rem_rot(vv, q, omega)
        return vv

    # Temperatur des Ensembles

    def thermometer(self):           # gibt Temperatur des Moleküls zurück
        self.ekin = 0.5*self.mass3.dot(self.vi**2)
        self.T = self.ekin*2/(3*self.N*kbinau)

    def update_kinetics(self):      # Ekin and T of the current self.vi go into self.data (written by write_output)
        self.thermometer()
        self.data['temperature'] = self.T
        self.data['Ekin'] = self.ekin

    def change_v(self, v):          # gibt v*s zurück, mit s als Korrekturfaktor - siehe Berendsen Thermostat
        if self.en_thermo == True and self.T > 0:   # enable thermostate (T=0 can not be rescaled)
            v = v * np.sqrt(1+self.dt/self.tau * ((self.T_soll/self.T) - 1))
        return v

    # Schreibefunktionen der errechnete Trajektorie 
    def write_trajectory(self, q, time, opt): # schreibt _dynamics.xyz-file, enhalten: Atomkoordinaten für vmd Darstellung
        with open('{0}_{1}.xyz'.format(self.jobname, self.dynamics), opt) as f:
            f.write(str(self.N)+ '\n\n')
            f.writelines(['{0:<2s} {1[0]:>20.16f} {1[1]:>20.16f} {1[2]:>20.16f} \n'.format(n, r) for n, r in zip(self.n, q.reshape(-1, 3)*aulen)])
    def write_dynamic(self, q, v, time, opt): # schreibt _dynamics.out-file, enthalten: Atomkoordinaten und Geschwindigkeiten
        with open('{}_{}.out'.format(self.jobname, self.dynamics), opt) as f:
            f.write(str(self.N)+ '\n\n')
            f.writelines(['{0:<2s} {1[0]:>20.16f} {1[1]:>20.16f} {1[2]:>20.16f} \n'.format(n, r) for n, r in zip(self.n, q.reshape(-1, 3))])
            f.writelines(['{0[0]:>20.16f} {0[1]:>20.16f} {0[2]:>20.16f} \n'.format(r) for r in v.reshape(-1, 3)])

    def log_time(self, opt): # one timestamp line per finished step, the cluster job script counts the lines of time.txt
        with open('time.txt', opt) as f:
            f.write('{}\n'.format(datetime.now().astimezone().strftime('%a %d %b %H:%M:%S %Z %Y')))
    
    def write_output(self, time):
        wrst = '{}'.format(round(time/fs2au, 8))
        for i in range(len(self.getens[0][1])): # write
            if isinstance(self.data[self.getens[0][0][i]], np.ndarray):
                for j in range(self.getens[0][1][i]):
                    wrst = '{}\t{}'.format(wrst, self.data[self.getens[0][0][i]][j])
            else:
                wrst = '{}\t{}'.format(wrst, self.data[self.getens[0][0][i]])
        for i in range(len(self.getens[2][0])): # calc
            if isinstance(self.data[self.getens[2][0][i]], np.ndarray): 
                for j in range(self.getens[2][1][i]):
                    wrst = '{}\t{}'.format(wrst, self.data[self.getens[2][0][i]][j])
            else:
                wrst = '{}\t{}'.format(wrst, self.data[self.getens[2][0][i]])         
        with open('{}_{}.out'.format(self.jobname, self.Enname), 'a') as f:
            f.write('{}\n'.format(wrst))
    
    # moves molecule, eliminates translation and rotation
    def propagate(self, counter):
        self.q_plus_1()
        self.q_new = self.rem_schwerpunkt(self.q_new)
        self.a_new = self.grad_to_a(self.grad(self.q_new))
        self.v_plus_1()
        self.v_new = self.rem_trans_rot(self.v_new, self.q_new)
        self.qi = self.q_new
        self.vi = self.v_new
        self.thermometer()
        self.vi = self.change_v(self.v_new)
        self.update_kinetics()
        self.ai = self.a_new
        self.writer(counter)
        
    # write calculated data to file
    def writer(self, counter):
        if self.write == 2:
            self.write_dynamic(self.qi, self.vi, counter*self.dt, 'a')
            self.write_output(counter*self.dt)
            self.write_trajectory(self.qi, counter*self.dt, 'a')
    
    # start simulation 
    def simulate(self): 
        for i in range(self.n_steps): #step 0 is init
            self.propagate(i+1)
            self.log_time('a')

    def load_inits(self, initfile): #load samplet positions (N, 3) and velocities (3N) as arrays
        with open(initfile, 'r') as f:
            N = int(f.readline())
            rows = [f.readline().split() for i in range(2*N)]
        atoms = [element_d_rev[rd[0]] for rd in rows[:N]]
        pos = np.array([rd[1:4] for rd in rows[:N]], dtype=float)
        vs = np.array([rd[0:3] for rd in rows[N:]], dtype=float).ravel()
        return atoms, pos, vs, N

    def initcalculator(self, q, init): # schreibt Koordinaten q in temp.xyz und gibt die Init-Rechnung an das QC-Programm. Die Ergebnisse stehen danach in self.data.
       self.data = self.submit.initcalc(self.comname, self.tempxyz, self.N, self.n, q, self.fchkname, self.getnames, aulen, init)
